import React, { useState } from 'react';
import styles from './SignupPage.module.css'; // Import CSS module

const SignupPage = () => {
    const [email, setEmail] = useState('');
    const [username, setUsername] = useState('');
    const [password, setPassword] = useState('');
    const [verifyPassword, setVerifyPassword] = useState('');
    const [name, setName] = useState('');
    const [surname, setSurname] = useState('');
    const [rememberMe, setRememberMe] = useState(false);
    const [error, setError] = useState('');

    const handleSignup = () => {
        // Dummy validation, replace with actual signup logic
        if (password !== verifyPassword) {
            setError('Passwords do not match');
            return;
        }

        // Perform signup logic here (e.g., API call or authentication)
        console.log('Signup logic goes here');

        // Reset form fields
        setEmail('');
        setUsername('');
        setPassword('');
        setVerifyPassword('');
        setName('');
        setSurname('');
        setRememberMe(false);

        // Optionally, navigate to another page after successful signup
        // history.push('/dashboard');
    };

    const handleCheckboxChange = (e) => {
        setRememberMe(e.target.checked);
    };

    return (
        <div className={styles['signup-card']}>
            <div className={styles['card-content']}>
                <img src="assets/svg/person-circle.svg" alt="Logo" className={styles.logo} />
                <h2>Sign Up</h2>
                <input
                    type="email"
                    placeholder="Email"
                    value={email}
                    onChange={(e) => setEmail(e.target.value)}
                />
                <input
                    type="text"
                    placeholder="Username"
                    value={username}
                    onChange={(e) => setUsername(e.target.value)}
                />
                <input
                    type="text"
                    placeholder="Name"
                    value={name}
                    onChange={(e) => setName(e.target.value)}
                />
                <input
                    type="text"
                    placeholder="Surname"
                    value={surname}
                    onChange={(e) => setSurname(e.target.value)}
                />
                <input
                    type="password"
                    placeholder="Password"
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                />
                <input
                    type="password"
                    placeholder="Verify Password"
                    value={verifyPassword}
                    onChange={(e) => setVerifyPassword(e.target.value)}
                />
                <button onClick={handleSignup}>Sign Up</button>
                {error && <p className={styles['error-message']}>{error}</p>}
                <p className={styles['login-link']}>
                    Already have an account? <Link to="/login">Log in</Link>
                </p>
            </div>
        </div>
    );
};

export default SignupPage;
